INTERESTS = ["Working with data", "Building software", "Developing AI systems", "Cybersecurity", "Cloud systems", "Business analysis", "Research", "Product design", "Problem solving", "Communication"]


def ensure_catalog(db: Session) -> None:
    known = {s.name.casefold(): s for s in db.scalars(select(Skill)).all()}
    all_skills = {entry[0] for role in CAREERS for entry in role["skills"]}
    all_skills.update({"Excel", "JavaScript", "HTML & CSS", "Networking", "Linux", "Programming", "Business Analysis", "Communication", "Problem Solving", "Git", "Databases"})
    for name in all_skills:
        if name.casefold() not in known:
            row = Skill(name=name, category="soft" if name in {"Communication", "Problem Solving"} else "technical")
            db.add(row); db.flush(); known[name.casefold()] = row
    existing_interests = {name.casefold() for name in db.scalars(select(Interest.name)).all()}
    for name in INTERESTS:
        if name.casefold() not in existing_interests:
            db.add(Interest(name=name, category="career"))
    existing_roles = {role.slug: role for role in db.scalars(select(CareerRole)).all()}
    for definition in CAREERS:
        role = existing_roles.get(definition["slug"])
        if role is None:
            role = CareerRole(slug=definition["slug"], name=definition["name"], description=definition["description"], education=definition["education"], tools=definition["tools"], typical_projects=definition["projects"], industries=definition["industries"], min_experience=definition["min_experience"])
            db.add(role); db.flush()
            for skill_name, importance, required, level in definition["skills"]:
                db.add(CareerSkill(career_id=role.id, skill_id=known[skill_name.casefold()].id, importance=importance, required=required, required_level=level))
    if db.scalar(select(ScoringSetting).where(ScoringSetting.name == "default")) is None:
        db.add(ScoringSetting(name="default", weights=WEIGHTS, version=1))
    db.commit()
